import { databases } from "@/lib/appwrite";
import { DB_ID, COLLECTIONS } from "@/lib/appwrite";
import { Room, RoomPayload } from "@/types/room";

import { Query } from "appwrite";

const select = [
    "*",
    "creator.*",
];

export const RoomService = {
    list(search?: string) {
        const queries = [
            Query.equal("status", "OPEN"),
            Query.equal("isPublic", true),
            Query.orderDesc("$createdAt"), // Default order
            Query.select(select),
        ];

        if (search && search.trim()) {
            // requires full-text index on 'name' in Appwrite
            queries.push(Query.search("name", search));
        }

        return databases.listDocuments<Room>(
            DB_ID,
            COLLECTIONS.ROOMS,
            queries
        );
    },

    get(roomId: string) {
        return databases.getDocument<Room>(
            DB_ID,
            COLLECTIONS.ROOMS,
            roomId,
            [
                Query.select(select),
            ]
        );
    },

    create(payload: RoomPayload) {
        return databases.createDocument(
            DB_ID,
            COLLECTIONS.ROOMS,
            "unique()",
            {
                ...payload,
                status: "OPEN",
            }
        ) as unknown as Room;
    },

    close(roomId: string) {
        return databases.updateDocument(
            DB_ID,
            COLLECTIONS.ROOMS,
            roomId,
            {
                status: "CLOSED",
            }
        );
    },

    open(roomId: string) {
        return databases.updateDocument(
            DB_ID,
            COLLECTIONS.ROOMS,
            roomId,
            {
                status: "OPEN",
                closedAt: null,
            }
        );
    },
};
